import requests
from typing import Protocol, runtime_checkable

class FileWrapper:
    def __getattr__(self, name):
        if name == 'read':
            return lambda length=None: b'file content'
        raise AttributeError(name)

def test_file_wrapper():
    files = {'file': ('test.txt', FileWrapper())}
    # We use a mock server or just check if it fails during encoding
    # The issue is in _encode_files, which is called during request preparation.
    try:
        requests.post('http://httpbin.org/post', files=files)
        print("Success")
    except Exception as e:
        print(f"Failed: {e}")

if __name__ == "__main__":
    test_file_wrapper()
