import requests
from requests.models import Request
from unittest.mock import MagicMock

class FileWrapper:
    def __init__(self):
        self.read_called = False
    def __getattr__(self, name):
        if name == 'read':
            def read_impl(length=None):
                self.read_called = True
                return b'file content'
            return read_impl
        raise AttributeError(name)

def test_file_wrapper():
    wrapper = FileWrapper()
    files = {'file': ('test.txt', wrapper)}
    req = Request('POST', 'http://example.com', files=files)
    prep = req.prepare()

    if wrapper.read_called:
        print("Requests read the file")
    else:
        print("Requests did NOT read the file (urllib3 might have)")

if __name__ == "__main__":
    test_file_wrapper()
